#nullable enable
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using Xunit;
using Alundra.Rendering.Effects;
using Alundra.Tests.Support;

namespace Alundra.Tests.Rendering.Effects;

/// <summary>
/// The golden table of E19.g G3a (<c>docs/plan-e19-g1g3-annexe/g3a-golden.tsv</c>, generated by <c>g3a-golden.py</c> from the oracles of the
/// binary and committed before the code) and the real export, shared by the effect tests. A missing file fails the test naming it: it never self-skips.
/// </summary>
internal static class EffectGolden
{
    internal sealed record AnimationRow(string Key, bool Destroy, int Life, int LastDrawn, int FreeTick, int FirstIdsv, int[][] Frames, int FirstImages)
    {
        public bool MapTable => Key[0] == 'm';
        public int MapId => MapTable ? int.Parse(Key.Split(':')[0][1..]) : -1;
        public int Effect => int.Parse(Key.Split(':')[1]);
        public int Animation => int.Parse(Key.Split(':')[2]);
    }

    internal sealed record LoadRow(int Map, int Slot, int Record, int XPx, int YPx, int ZPx);

    internal sealed record ZoneRow(int Map, int Record, int X1, int Y1, int X2, int Y2);

    internal static readonly string[][] Rows = Read();

    internal static IEnumerable<string[]> Of(string tag) => Rows.Where(r => r[0] == tag);

    internal static IEnumerable<string[]> Scenario(string name) => Rows.Where(r => r[0] == "S" && r[1] == name);

    internal static IReadOnlyList<AnimationRow> Animations { get; } = Of("A").Select(r => new AnimationRow(
        r[1], r[2] == "destroy", int.Parse(r[3]), r[4] == "-" ? -1 : int.Parse(r[4]), r[5] == "-" ? -1 : int.Parse(r[5]), int.Parse(r[7]),
        r[8].Split(';').Select(f => f.Split(':').Select(int.Parse).ToArray()).ToArray(), int.Parse(r[9]))).ToList();

    internal static IReadOnlyList<LoadRow> Loads { get; } = Of("L").Select(r => new LoadRow(
        int.Parse(r[1]), int.Parse(r[2]), int.Parse(r[3]), int.Parse(r[4]), int.Parse(r[5]), int.Parse(r[6]))).ToList();

    internal static IReadOnlyList<ZoneRow> Zones { get; } = Of("Z").Select(r => new ZoneRow(
        int.Parse(r[1]), int.Parse(r[2]), int.Parse(r[3]), int.Parse(r[4]), int.Parse(r[5]), int.Parse(r[6]))).ToList();

    private static string[][] Read()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null)
        {
            var candidate = Path.Combine(directory.FullName, "docs", "plan-e19-g1g3-annexe", "g3a-golden.tsv");
            if (File.Exists(candidate))
            {
                return File.ReadAllLines(candidate).Where(l => l.Length > 0 && l[0] != '#').Select(l => l.Split('\t')).ToArray();
            }

            directory = directory.Parent;
        }

        throw new InvalidOperationException($"EffectGolden: no 'docs/plan-e19-g1g3-annexe/g3a-golden.tsv' found above '{AppContext.BaseDirectory}'.");
    }

    /// <summary>The name of the world of a map id (the leaf of its entry of <c>Maps/world-index.json</c>), null when the map is not in the export.</summary>
    internal static string? WorldNameOf(string projectRoot, int mapId)
    {
        var index = JsonSerializer.Deserialize<Dictionary<string, string>>(File.ReadAllText(Path.Combine(projectRoot, "Maps", "world-index.json")))!;
        return index.TryGetValue(mapId.ToString(), out var path) ? Path.GetFileNameWithoutExtension(path.Replace('\\', '/')) : null;
    }

    internal static IReadOnlyList<int> AllMapIds(string projectRoot)
    {
        var index = JsonSerializer.Deserialize<Dictionary<string, string>>(File.ReadAllText(Path.Combine(projectRoot, "Maps", "world-index.json")))!;
        return index.Keys.Select(int.Parse).OrderBy(i => i).ToList();
    }

    internal static EffectBank BankOf(string projectRoot, int mapId) =>
        EffectBankLoader.Load(projectRoot, WorldNameOf(projectRoot, mapId));

    /// <summary>A bank with one map table (<paramref name="animations"/>, one image set per index) and the given records.</summary>
    internal static EffectBank Synthetic(EffectAnimation[] animations, int imageSets, params EffectRecord[] records)
    {
        var table = new EffectTable { Animations = animations.ToList() };
        for (var i = 0; i < imageSets; i++)
        {
            table.ImageSets.Add(new EffectImageSet { Idsv = 10 + i, Images = { new EffectImage { W = 1 + i, H = 1 } } });
        }

        return new EffectBank(new EffectDocument { Records = records.ToList(), Effects = { table } }, null);
    }

    internal static EffectAnimation Anim(string end, params int[][] frames) => new() { End = end, Frames = frames };

    internal static EffectRecord Record(int flags, int x, int y, int z, int anim, int x1 = 0, int y1 = 0, int x2 = 51, int y2 = 59, int effect = 0) =>
        new() { X1 = x1, X2 = x2, Y1 = y1, Y2 = y2, Flags = flags, Effect = effect, X = x, Y = y, Z = z, Anim = anim };
}
